// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }

    function testFuzz_property(address depositor, uint256 amt) public {
        vm.assume(depositor != address(0));
        amt = bound(amt, 0, 1 ether);

        vm.deal(depositor, amt);
        vm.prank(depositor);
        (bool okDeposit, ) = address(c).call{value: amt}("");
        require(okDeposit);

        vm.prank(depositor);
        bool okWithdraw;
        try c.withdraw() {
            okWithdraw = true;
        } catch {
            okWithdraw = false;
        }

        if (okWithdraw) {
            assertTrue(c.balances(depositor) == 0);
        } else {
            assertTrue(c.balances(depositor) >= 0);
        }
    }
}
